struct Row { let id: UUID; var flag: Bool }

// Slow: the undo entry shares the buffer, so the next append copies all of it
final class SlowEditor {
  private(set) var rows: [Row] = []
  private var undo: [[Row]] = []

  func append(_ row: Row) {
    undo.append(rows)        // storage now has two owners
    rows.append(row)         // not unique -> copies n elements. O(n^2) overall
  }
}

// Fast: record the operation, keep the buffer uniquely referenced
enum Edit { case inserted(index: Int) }

final class FastEditor {
  private(set) var rows: [Row] = []
  private var undo: [Edit] = []

  init(expected: Int) { rows.reserveCapacity(expected) }   // no repeated regrowth

  func append(_ row: Row) {
    undo.append(.inserted(index: rows.count))
    rows.append(row)         // uniquely referenced -> appends in place
  }

  func setFlag(at index: Int) {
    rows[index].flag = true  // in-place through the subscript
    // var copy = rows[index]; copy.flag = true; rows[index] = copy  // copies the element
  }
}

// The same test the standard library uses, available to your own CoW types
final class Storage { var rows: [Row] = [] }

struct Document {
  private var storage = Storage()
  mutating func append(_ row: Row) {
    if !isKnownUniquelyReferenced(&storage) {
      storage = Storage()    // deep copy here, once, on first write after sharing
    }
    storage.rows.append(row)
  }
}

