// Cooperative: a compute loop has to ask, or cancellation is ignored
func downsampleAll(_ payloads: [Data]) throws -> [UIImage] {
  try payloads.map { data in
    try Task.checkCancellation()
    return downsample(data)
  }
}

// Ships a watchdog kill: launch parks the main thread on the network
func application(_ app: UIApplication,
                 didFinishLaunchingWithOptions options: [UIApplication.LaunchOptionsKey: Any]?) -> Bool {
  let semaphore = DispatchSemaphore(value: 0)
  var remote: Config?
  RemoteConfig.fetch { remote = $0; semaphore.signal() }
  semaphore.wait()                 // main thread frozen until the server answers
  Theme.apply(remote ?? .fallback)
  return true
}

// Launch with what you already have; refresh after the first frame
func application(_ app: UIApplication,
                 didFinishLaunchingWithOptions options: [UIApplication.LaunchOptionsKey: Any]?) -> Bool {
  Theme.apply(Config.cached ?? .fallback)
  MXMetricManager.shared.add(HangReporter.shared)

  Task.detached(priority: .utility) {
    if let fresh = try? await RemoteConfig.fetch() {
      await MainActor.run { Theme.apply(fresh) }
    }
  }
  return true
}

// The field answer: hang stacks and watchdog exits from real devices
import MetricKit

final class HangReporter: NSObject, MXMetricManagerSubscriber {
  static let shared = HangReporter()

  func didReceive(_ payloads: [MXDiagnosticPayload]) {
    for hang in payloads.flatMap({ $0.hangDiagnostics ?? [] }) {
      upload(duration: hang.hangDuration, stacks: hang.callStackTree.jsonRepresentation())
    }
  }

  func didReceive(_ payloads: [MXMetricPayload]) {
    for payload in payloads {
      let watchdogKills = payload.applicationExitMetrics?
        .foregroundExitData.cumulativeAppWatchdogExitCount
      report(watchdogKills)
    }
  }
}

