// Cheap cell: the same look, no offscreen work in the frame loop
final class CardCell: UICollectionViewCell {
  let photo = UIImageView()

  override func layoutSubviews() {
    super.layoutSubviews()
    // An explicit path: the render server rasterises a known shape, no scratch buffer
    layer.shadowPath = UIBezierPath(roundedRect: bounds, cornerRadius: 16).cgPath
  }

  func style() {
    layer.shadowOpacity = 0.2
    layer.shadowRadius = 12
    photo.isOpaque = true
    photo.backgroundColor = .systemBackground   // opaque -> nothing to blend
  }

  // Round the bitmap once, off the frame loop, instead of clipping every frame
  func configure(with image: UIImage, radius: CGFloat) {
    let size = image.size
    photo.image = UIGraphicsImageRenderer(size: size).image { _ in
      UIBezierPath(roundedRect: CGRect(origin: .zero, size: size),
                   cornerRadius: radius).addClip()
      image.draw(at: .zero)
    }
  }
}

