import Foundation
import os

// The number jetsam actually uses, readable from inside the app
func physFootprint() -> UInt64 {
  var info = task_vm_info_data_t()
  var count = mach_msg_type_number_t(MemoryLayout<task_vm_info_data_t>.size / MemoryLayout<natural_t>.size)
  let status = withUnsafeMutablePointer(to: &info) {
    $0.withMemoryRebound(to: integer_t.self, capacity: Int(count)) {
      task_info(mach_task_self_, task_flavor_t(TASK_VM_INFO), $0, &count)
    }
  }
  return status == KERN_SUCCESS ? UInt64(info.phys_footprint) : 0
}

// Headroom before the process is killed, not "free RAM on the device"
func headroomMB() -> Int { os_proc_available_memory() / (1024 * 1024) }

func importIfSafe(_ url: URL) throws -> [Record] {
  guard headroomMB() > 120 else { throw ImportError.lowMemory }

  // Dirty: the whole file is copied into anonymous memory and charged to you
  // let data = try Data(contentsOf: url)

  // Clean: file-backed pages the kernel can evict and re-read under pressure
  let data = try Data(contentsOf: url, options: .mappedIfSafe)

  return try autoreleasepool {
    try JSONDecoder().decode([Record].self, from: data)
  }
}

