// Slow shape: boxed existentials, an open class, retain traffic per element
class Shape {                              // subclassable -> vtable dispatch
  func area() -> Double { 0 }
}

func totalArea(_ shapes: [any Renderable]) -> Double {   // boxed + witness table
  shapes.reduce(0) { $0 + $1.area() }                    // retain/release per element
}

// Fast shape: the compiler can see the whole thing and delete the bookkeeping
protocol Renderable { func area() -> Double }

struct Rect: Renderable {                  // value type: no refcount at all
  let w, h: Double
  func area() -> Double { w * h }
}

func totalArea<S: Sequence>(_ shapes: S) -> Double where S.Element: Renderable {
  shapes.reduce(0) { $0 + $1.area() }      // specialised, inlined, direct call
}

// When the elements must be classes: final + native storage
final class Node {                         // final -> static dispatch
  var weight: Double = 0
}

func totalWeight(_ nodes: ContiguousArray<Node>) -> Double {
  // ContiguousArray guarantees native storage: no bridged-array check per access
  nodes.reduce(0) { $0 + $1.weight }
}

