// Know what you dropped instead of discovering it in a memory graph
final class UploadQueue {
  private let continuation: AsyncStream<Job>.Continuation
  private var dropped = 0

  init(continuation: AsyncStream<Job>.Continuation) {
    self.continuation = continuation
    continuation.onTermination = { @Sendable _ in }
  }

  func submit(_ job: Job) {
    if case .dropped = continuation.yield(job) {   // .bufferingOldest(64) upstream
      dropped += 1
      Metrics.count("upload.queue.dropped", dropped)
    }
  }
}

