// Block-based observers are kept by the center until you remove the token
final class Screen {
  private var token: NSObjectProtocol?

  func observe() {
    token = NotificationCenter.default.addObserver(
      forName: .didSync, object: nil, queue: .main) { _ in }
  }

  deinit {
    if let token { NotificationCenter.default.removeObserver(token) }
  }
}
